-- 99_VERIFY_ROLLED_BACK (read only). R1 = 0 rows. R2 = VALID.
SELECT 'R1' AS CHK, NAME, TYPE, COUNT(*) AS MARKER_LINES FROM USER_SOURCE WHERE TEXT LIKE '%E20261102-RTFLATESTPRICE%' GROUP BY NAME, TYPE;
SELECT 'R2' AS CHK, OBJECT_NAME, OBJECT_TYPE, STATUS FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW','PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE') AND OBJECT_TYPE IN ('PROCEDURE', 'PACKAGE BODY') ORDER BY 2, 3;
